import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * THE RISO POP CONTRACT, ASSERTED.
 *
 * The palette is not typed by hand anywhere in the app: it is GENERATED by
 * docs/brand/build-theme.mjs, which measures every rendered foreground/ground
 * pair against WCAG AA and refuses to emit a failing one. That guarantee only
 * holds for the app if what ships in src/theme.css and src/index.css is the
 * generator's output and not somebody's memory of it — so this test reads both
 * ends and fails on any drift.
 *
 * The icon files get the same treatment: content/icon.svg is the Logo
 * component's 32-unit geometry placed by one transform, and both wear the riso
 * inks. A hex here is legitimate ONLY because it is comparing against the
 * generated file, never asserting a colour from taste.
 */

const at = (rel: string) => resolve(__dirname, '../../..', rel);
const read = (rel: string) => readFileSync(at(rel), 'utf8');

/** Every `--c-name: R G B;` pair in one block of CSS, as a map. */
function tokens(css: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const m of css.matchAll(/--c-([a-z-]+):\s*([\d ]+);/g)) out[m[1]] = m[2].trim();
  return out;
}

/** The `:root { … }` and `.dark { … }` rooms of a palette file. */
function rooms(css: string): { light: Record<string, string>; dark: Record<string, string> } {
  const darkAt = css.indexOf('.dark {');
  return { light: tokens(css.slice(0, darkAt)), dark: tokens(css.slice(darkAt)) };
}

/** `255 200 92` -> `#FFC85C`. The CSS carries triplets; SVG carries hex. */
const asHex = (triplet: string): string =>
  '#' + triplet.split(' ').map((n) => Number(n).toString(16).padStart(2, '0')).join('').toUpperCase();

/**
 * THE BRAND AMBER, READ FROM THE GENERATOR RATHER THAN REMEMBERED.
 *
 * This used to be the literal `#FFD21E` typed into two assertions below, and
 * that is exactly the drift this file exists to catch: when the palette moved
 * to the marketing site's #FFC85C, the icons and the theme could have parted
 * company with both tests still green, because the tests were pinning a
 * snapshot instead of the invariant. The invariant is "the icon tile IS
 * --c-primary-fixed", so that is what is asserted.
 */
const AMBER = asHex(rooms(read('docs/brand/riso-pop.theme.css')).light['primary-fixed']);

describe('the shipped palette is the generated palette', () => {
  const generated = rooms(read('docs/brand/riso-pop.theme.css'));
  const shipped = rooms(read('apps/classroom/src/theme.css'));

  it('carries all 47 tokens in the light room, value for value', () => {
    expect(Object.keys(generated.light).length).toBe(47);
    expect(shipped.light).toEqual(generated.light);
  });

  it('carries the dark room too', () => {
    expect(shipped.dark).toEqual(generated.dark);
  });

  it('says it is generated, so nobody hand-edits a measured value', () => {
    expect(read('apps/classroom/src/theme.css')).toContain('GENERATED by docs/brand/build-theme.mjs');
  });
});

describe('the subject tints are the generated tints', () => {
  it('ships every generated tile, ring and ink class with both room values', () => {
    const index = read('apps/classroom/src/index.css');
    const lines = read('docs/brand/riso-pop.tints.css').matchAll(
      /\.((?:tile|ring-tint|ink)-[a-z]+)\s*\{\s*(@apply [^;]+;)/g,
    );
    let seen = 0;
    for (const [, className, apply] of lines) {
      seen++;
      // The class and its full @apply — light and dark value together — must
      // appear verbatim, or a student's dark room shows the light wash.
      const rule = new RegExp(`\\.${className}\\s*\\{\\s*${apply.replace(/[[\]()/\\]/g, '\\$&')}`);
      expect(index, `${className} drifted from the generated tint`).toMatch(rule);
    }
    expect(seen).toBe(12);
  });
});

describe('the icons wear the riso inks on the shared geometry', () => {
  for (const rel of ['content/icon.svg', 'content/icon-maskable.svg']) {
    describe(rel, () => {
      const svg = read(rel);

      it('has dropped the old indigo tile', () => {
        expect(svg.toLowerCase()).not.toContain('#4648d4');
      });

      it('keeps the 32-unit geometry the Logo component draws', () => {
        // Two orbits, one nucleus, the electron at the top of its arc — the
        // icon is the component placed by a transform, so these are literal.
        expect(svg.match(/rx="14" ry="6\.2"/g)?.length).toBe(2);
        expect(svg).toContain('r="4"');
        expect(svg).toContain('cx="9.9" cy="-9.9" r="2.2"');
      });

      /**
       * BOTH ORBITS ARE THE BLUE PLATE, AND NO FLUORO IS IN THE MARK.
       *
       * This used to assert that #FF48A0 was present — it was pinning the pink
       * INTO the logo. The brand is two primaries, amber and blue, and law 1
       * says fluoro is a ground and never the thing you read; a mark that was
       * half pink made pink half the brand. So the assertion is inverted: the
       * blue is there, the fluoro is not.
       */
      it('draws both orbits on the blue plate, with no fluoro in the mark', () => {
        expect(svg).toContain('#0B5FD9');
        expect(svg, 'fluoro pink is back in the mark').not.toContain('#FF48A0');
      });

      it('sits on the amber tile with an ink keyline — law 3', () => {
        expect(svg, 'the tile is not --c-primary-fixed').toContain(AMBER);
        // The keyline the law is about: an ink-STROKED rect bounding the tile,
        // heavy enough to survive a launcher's downscale. Asserting "some ink
        // stroke exists" was satisfiable by the electron's outline alone, which
        // would let the tile keyline vanish with the test still green.
        const keyline = svg.match(/<rect[^>]*stroke="#17171D"[^>]*stroke-width="([\d.]+)"/);
        expect(keyline, 'no ink-stroked rect bounds the yellow tile').not.toBeNull();
        expect(Number(keyline![1])).toBeGreaterThanOrEqual(8);
      });
    });
  }
});

describe('the maskable icon survives the Android adaptive viewport', () => {
  // tools/bin/make-app-icons.mjs renders this same SVG 1:1 as the Android
  // adaptive FOREGROUND layer. Two croppings apply and the smaller one wins:
  // PWA maskable masks keep at least the central 80% circle (r=204.8 at 512),
  // but Android shows only the central 72/108dp of an adaptive layer and
  // guarantees nothing outside the 66/108dp safe circle — r=156.4 at 512.
  // A keyline outside that circle is cropped off every real launcher, leaving
  // yellow unbounded (law 3 broken) exactly where most students see the mark.
  const svg = read('content/icon-maskable.svg');

  it('grounds the full bleed in paper, so cropping loses nothing lawful', () => {
    expect(svg).toMatch(/<rect width="512" height="512"[^>]*fill="#FAF7F0"/);
  });

  it('keeps the amber tile — corners included — inside the 66dp safe circle', () => {
    const tile = svg.match(
      new RegExp(
        `<rect x="([\\d.]+)" y="([\\d.]+)" width="([\\d.]+)" height="([\\d.]+)" rx="([\\d.]+)" fill="${AMBER}"`,
      ),
    );
    expect(tile, 'no inset amber tile rect found').not.toBeNull();
    const [, x, , w, , rx] = tile!.map(Number);
    // Farthest yellow from centre: out along the diagonal to the rounded
    // corner's arc centre, then its radius in any direction.
    const half = w / 2;
    const cornerReach = Math.SQRT2 * (half - rx) + rx;
    expect(Math.abs(x + half - 256), 'tile is not centred').toBeLessThan(1);
    expect(cornerReach).toBeLessThanOrEqual((66 / 108) * 256);
  });
});

describe('index.css holds the law-3 backstop for token grounds', () => {
  const index = read('apps/classroom/src/index.css');

  it('keylines every unbordered bg-primary-fixed ground', () => {
    // --c-primary-fixed IS riso yellow now, and a dozen screens use it as a
    // chip or circle ground straight on paper. The generator audits pairs,
    // not usage, so the keyline lands as one rule here instead of twelve
    // screen edits. Screens already pairing it with border-primary keep
    // their blue keyline (4.5:1 on paper — a legitimate bound).
    expect(index).toMatch(/\.bg-primary-fixed:not\(\.border-primary\)/);
    expect(index).toMatch(/outline:\s*2px solid rgb\(var\(--c-on-primary-fixed\)\)/);
  });

  it('carries no pre-riso indigo in the soft shadows', () => {
    // .shadow-soft-indigo keeps its NAME (26 read-only call sites) but its
    // colour is owned here and must sit with the riso ink, not a dead brand.
    expect(index).not.toContain('99, 102, 241');
  });
});

describe('the generator still refuses, and the rasters carry the riso grounds', () => {
  it('build-theme.mjs exits clean: pairs audited AND committed CSS is its output', () => {
    // Without this, nothing in CI ever RUNS the script whose refusal the
    // whole contract leans on. Its check mode also fails on drift between
    // its constants and the committed docs/brand CSS, closing the loop:
    // script → committed files → (file-equality tests above) → the app.
    const out = execFileSync('node', ['docs/brand/build-theme.mjs'], {
      cwd: at('.'),
      encoding: 'utf8',
    });
    expect(out).toContain('PAIRS PASS');
  });

  // The PNGs cannot be diffed as text, so pin the exact grounds that
  // tools/bin/make-app-icons.mjs would silently regress if re-run before its
  // recorded handoff lands (stale splash grounds, flatten-everything).
  const px = async (rel: string, x: number, y: number) => {
    const sharp = (await import('sharp')).default;
    const raw = await sharp(at(rel))
      .extract({ left: x, top: y, width: 1, height: 1 })
      .ensureAlpha()
      .raw()
      .toBuffer();
    return [raw[0], raw[1], raw[2], raw[3]];
  };

  it('splash grounds are riso paper and the dark surface', async () => {
    expect(await px('apps/classroom/assets/splash.png', 2, 2)).toEqual([250, 247, 240, 255]);
    expect(await px('apps/classroom/assets/splash-dark.png', 2, 2)).toEqual([20, 19, 24, 255]);
  });

  it('the adaptive background layer is paper, matching the maskable ground', async () => {
    expect(await px('apps/classroom/assets/icon-background.png', 2, 2)).toEqual([
      250, 247, 240, 255,
    ]);
  });

  it('icon-512 keeps its rounded-corner alpha', async () => {
    const [, , , a] = await px('content/icon-512.png', 0, 0);
    expect(a).toBe(0);
  });
});

describe('the install surfaces agree with the palette', () => {
  it('manifest theme and background are riso paper', () => {
    const manifest = JSON.parse(read('content/manifest.webmanifest'));
    expect(manifest.theme_color.toUpperCase()).toBe('#FAF7F0');
    expect(manifest.background_color.toUpperCase()).toBe('#FAF7F0');
  });

  it('index.html pre-paint light chrome matches :root --c-background', () => {
    // theme.test.ts pins the dark half of this; here is the light half.
    const light = rooms(read('apps/classroom/src/theme.css')).light['background'];
    const hex =
      '#' + light.split(' ').map((n) => Number(n).toString(16).padStart(2, '0')).join('');
    expect(read('apps/classroom/index.html').toLowerCase()).toContain(hex);
  });
});
